import os, sys, tempfile, time, unittest
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
import ivi_bridge as B

ORCA = """; HEADER_BLOCK_START
; generated by OrcaSlicer 2.5.0-rc on 2026-11-01 at 10:12:44
; total layer number: 3
; filament_density: 1.04
; filament_diameter: 1.75
; max_z_height: 0.90
; HEADER_BLOCK_END

; THUMBNAIL_BLOCK_START
; THUMBNAIL_BLOCK_END

M73 P0 R357
M140 S100
M104 S250
G90
M83
G28
G1 Z0.3 F600
G1 X-20 Y-10 F6000
G1 X20 Y-10 E2.5 F1800
G1 X20 Y15 E1.6
G1 Z0.6
G1 X-20 Y15 E2.5 ; perimeter
G1 X-30 Y40 F6000 ; travel only
G92 E0
G1 Z0.9 E-0.8
M73 P100 R0
; filament used [mm] = 1234.56
; filament used [g] = 3.71
; total filament used [g] = 3.71
; estimated printing time (normal mode) = 5h 58m 3s

; CONFIG_BLOCK_START
; bed_temperature = 100
; filament_type = ABS
; hot_plate_temp = 100,100
; nozzle_diameter = 0.3
; nozzle_temperature = 250,250
; sparse_infill_speed = 120
; CONFIG_BLOCK_END
"""

class HeaderTests(unittest.TestCase):
    def w(self, text):
        d = tempfile.mkdtemp(); p = os.path.join(d, "a.gcode")
        with open(p, "w", newline="") as f: f.write(text)
        return p
    def hdr(self, p):
        return open(p, encoding="utf-8").read().split(";Header End")[0]
    def test_orca_sample(self):
        p = self.w(ORCA); self.assertTrue(B.add_ivi_header(p, nozzle=0.4, date="2026-11-01 12:00:00"))
        h = self.hdr(p); out = open(p, encoding="utf-8").read()
        self.assertTrue(out.startswith(";Header Start\n\n; HEADER_BLOCK_START\n\n;header_type: 3dp,0.3mm\n"))
        n = ORCA.count("\n"); valid = sum(1 for l in ORCA.splitlines() if l.strip() and not l.strip().startswith(";"))
        for s in (";file_total_lines: %d" % (n + 20), ";file_valid_lines: %d" % valid, ";estimated_time(s): 21483",
                  ";filament_used(m): 1.23", ";filament_weight(g): 3.71", ";material_type: ABS",
                  ";nozzle_temperature(°C): 250", ";build_plate_temperature(°C): 100", ";work_speed(mm/minute): 7200",
                  ";max_x(mm): 20.00", ";max_y(mm): 15.00", ";max_z(mm): 0.60", ";min_x(mm): -20.00",
                  ";min_y(mm): -10.00", ";min_z(mm): 0.30"):
            self.assertIn(s + "\n", h)
        self.assertLess(h.index("estimated_time"), h.index("filament_used"))
        self.assertLess(h.index("filament_weight"), h.index("material_type"))
        self.assertIn(";Header End\n\n;G-code for 3dp engraving\n;Generated by IVI 3licer\n;2026-11-01 12:00:00\n\n; generated by OrcaSlicer", out)
        self.assertEqual(out.count("; HEADER_BLOCK_START"), 1)       # moved, not duplicated
        self.assertTrue(out.endswith("; CONFIG_BLOCK_END\n"))
        self.assertEqual(B.clean_gcode(out), B.clean_gcode(ORCA))   # G-code itself untouched
        self.assertFalse(B.add_ivi_header(p)); self.assertEqual(open(p, encoding="utf-8").read(), out)  # idempotent
    def test_m73_fallback_and_defaults(self):
        p = self.w(ORCA.replace("; estimated printing time (normal mode) = 5h 58m 3s\n", "").replace("; nozzle_diameter = 0.3\n", ""))
        B.add_ivi_header(p, nozzle=0.3); h = self.hdr(p)
        self.assertIn(";estimated_time(s): 21420\n", h); self.assertIn(";header_type: 3dp,0.3mm\n", h)
    def test_cura_style_and_max_z_fallback(self):
        p = self.w(";FLAVOR:Marlin\n;TIME:100\n;Generated with Cura_SteamEngine 5.0\n; max_z_height: 12.5\nG28\nG1 Z5\n")
        B.add_ivi_header(p); out = open(p, encoding="utf-8").read()
        self.assertTrue(out.startswith(";Header Start\n\n;FLAVOR:Marlin\n;TIME:100\n\n;header_type: 3dp,0.4mm"))
        self.assertIn(";max_z(mm): 12.50\n", out); self.assertIn(";material_type: PLA\n", out)
        self.assertIn("\n\n;Generated with Cura_SteamEngine 5.0\n", out)
    def test_relative_and_durations(self):
        self.assertEqual(B.parse_duration("1d 2h 3m 4s"), 93784); self.assertIsNone(B.parse_duration("n/a"))
        p = self.w("G91\nG1 X5 E1\nG1 X5 E1\nG90\n"); B.add_ivi_header(p); h = self.hdr(p)
        self.assertIn(";max_x(mm): 10.00", h); self.assertIn(";min_x(mm): 0.00", h)
    def test_copy_to_dst_and_cli(self):
        import ivi_add_header as C, io, contextlib
        p = self.w(ORCA); d = p + ".out"; buf = io.StringIO()
        with contextlib.redirect_stdout(buf): C.main([p, d])
        self.assertIn(";material_type: ABS", buf.getvalue()); self.assertEqual(open(p).read(), ORCA)
        self.assertTrue(open(d, encoding="utf-8").read().startswith(";Header Start"))
    def test_large_file_streams(self):
        body = "G1 X1 Y1 E0.1\n" * 600000
        p = self.w(ORCA + body); t = time.time(); B.add_ivi_header(p); dt = time.time() - t
        self.assertLess(dt, 20); self.assertTrue(open(p, encoding="utf-8").read().endswith("G1 X1 Y1 E0.1\n"))

class StripTests(unittest.TestCase):
    def w(self, text):
        p = os.path.join(tempfile.mkdtemp(), "a.gcode")
        with open(p, "w", newline="") as f: f.write(text)
        return p
    def read(self, p):
        with open(p, encoding="utf-8") as f: return f.read()
    def test_strip_and_counts_consistent(self):
        p = self.w(ORCA.replace("G90\n", "G90\nG21\nM204 P500 T1000 ; accel\nM205 X8 Y8 ; jerk\nM2040\nm73 p50 r3\n"))
        r = B.prepare_gcode(p, nozzle=0.3, date="d")
        out = self.read(p); self.assertTrue(r["header"])
        self.assertEqual(r["removed"], 6)   # M73 P0, M73 P100, m73 p50, G21, M204, M205
        body = out.split(";Header End", 1)[1]
        for c in ("M73", "m73", "G21", "M204", "M205"):
            self.assertFalse(any(l.strip().split(" ")[0] == c for l in body.splitlines()), c)
        self.assertIn("M2040\n", body)                       # different command, kept
        self.assertIn(";estimated_time(s): 21483\n", out)
        rest = body.split(";" + "d" + "\n\n", 1)[1]           # lines after the IVI preamble
        n_out = rest.count("\n") + 1                          # + the moved '; HEADER_BLOCK_START'
        self.assertIn(";file_total_lines: %d\n" % (n_out + 20), out)
        valid = sum(1 for l in rest.splitlines() if l.strip() and not l.strip().startswith(";"))
        self.assertIn(";file_valid_lines: %d\n" % valid, out)
    def test_m73_time_still_used_when_stripped(self):
        p = self.w("; generated by OrcaSlicer\nM73 P0 R10\nG1 X1 E1\n"); B.prepare_gcode(p)
        out = self.read(p); self.assertIn(";estimated_time(s): 600", out); self.assertNotIn("M73 P0", out)
    def test_existing_header_still_stripped(self):
        p = self.w(";Header Start\n;Header End\nG21\nM204 S100\nG1 X1\n")
        r = B.prepare_gcode(p); self.assertEqual(r, {"header": False, "removed": 2})
        self.assertEqual(self.read(p), ";Header Start\n;Header End\nG1 X1\n")
    def test_stripped_line_inside_head(self):
        p = self.w(";FLAVOR:Marlin\nG21\n;TIME:5\n;Generated with Cura\nG1 X1\n"); B.prepare_gcode(p)
        out = self.read(p); self.assertIn(";FLAVOR:Marlin\n;TIME:5\n\n;header_type", out)
        self.assertTrue(out.endswith(";Generated with Cura\nG1 X1\n")); self.assertNotIn("G21", out)
    def test_custom_list_and_off(self):
        p = self.w("G21\nM204 S1\nM107\n"); r = B.prepare_gcode(p, header=False, strip=["m107"])
        self.assertEqual((r["removed"], self.read(p)), (1, "G21\nM204 S1\n"))
        q = self.w("G21\n"); self.assertEqual(B.prepare_gcode(q, header=False, strip=[]), {"header": False, "removed": 0})
    def test_cli_strips(self):
        import ivi_add_header as C, io, contextlib
        p = self.w(ORCA); d = p + ".out"
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()): C.main([p, d])
        self.assertNotIn("M73 P0", self.read(d)); self.assertIn("M73 P0", self.read(p))
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()): C.main([p, d, "--strip", ""])
        self.assertIn("M73 P0", self.read(d))

if __name__ == "__main__": unittest.main()
